<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { Building2,Plus,Ticket,Handshake,Construction,Landmark,Users,WalletCards,Sparkles,Dices,Check,Trash2,Star,MapPin,Crown,ChevronRight,RefreshCw,Play,ShieldCheck,Car,UtensilsCrossed,Lightbulb,Wifi,Armchair,Goal,Store,Timer,KeyRound } from '@lucide/vue'
import { api } from '../../services/api'
import { authStore } from '../../stores/auth'
import { uiStore } from '../../stores/ui'
import { money,number,date } from '../../utils'
import PageHeader from '../../components/PageHeader.vue'
import LoadingBlock from '../../components/LoadingBlock.vue'
import EmptyState from '../../components/EmptyState.vue'
import BaseModal from '../../components/BaseModal.vue'
import StadiumArena from '../../components/StadiumArena.vue'
import StadiumCompliancePanel from '../../components/StadiumCompliancePanel.vue'

const isAdmin=computed(()=>authStore.isAdmin.value)
const loading=ref(true),busy=ref(false),active=ref('overview'),clubs=ref([]),clubId=ref(authStore.user.value?.clubId||''),data=ref(null),operationsData=ref(null),operationRows=ref([]),operationMeta=ref({page:1,pages:1,total:0}),catalog=ref([]),brands=ref([]),publicStadiums=ref([]),modal=ref(''),selectedStadium=ref(null),selectedMatch=ref(null),selectedFinance=ref(null),selectedStatement=ref(null)
const stadiumForm=ref({name:'',city:'',country_name:'Việt Nam',capacity_total:12000,standard_seats:11000,vip_seats:1000,hospitality_boxes:4,default_standard_ticket:100000,default_vip_ticket:500000,concession_per_head:35000,parking_per_head:8000,pitch_quality:48,seating_quality:45,stands_quality:45,lighting_quality:50,technology_quality:38,hospitality_quality:35,parking_quality:40,security_quality:50,commercial_quality:38,atmosphere_quality:52,relationship_type:'OWNED'})
const matchForm=ref({stadium_id:'',simulation_mode:'RANDOM',occupancy_pct:75,standard_ticket_price:120000,vip_ticket_price:600000})
const sponsorForm=ref({match_id:'',stadium_id:'',brand_id:'',offer_type:'MATCH_PARTNER',amount:'1000000000'})
const rentForm=ref({stadium_id:'',relationship_type:'LEASED',lease_fee_per_match:'200000000',owner_revenue_share_pct:'5',starts_on:'',ends_on:''})
const requestForm=ref({source_match_id:'',stadium_id:'',proposed_fee:0,proposed_owner_share_pct:5,note:''})
const matchFilters=ref({q:'',team:'',stadium_id:'',competition_id:'',season_id:'',brand_id:'',match_kind:'',timing:'ALL',ad_status:'',eligibility_status:'',assignment_method:'',min_value:'',max_value:'',date_from:'',date_to:'',sort:'NEWEST',page:1,limit:30})
const sponsorFilters=ref({q:'',status:'',season_id:'',competition_id:'',stadium_id:'',brand_id:''})
const tabs=[['overview','Tổng quan sân',Building2],['compliance','Kiểm định sân',ShieldCheck],['matchday','Ngày thi đấu',Ticket],['operations','Phân sân & sao kê',Landmark],['sponsors','Tài trợ',Handshake],['upgrades','Nâng cấp',Construction]]
const currentClub=computed(()=>data.value?.club)
const stadiums=computed(()=>data.value?.stadiums||[])
const primaryStadium=computed(()=>stadiums.value.find(s=>s.is_primary)||stadiums.value[0])
const matches=computed(()=>data.value?.matchdays||[])
const offers=computed(()=>data.value?.offers||[])
const upgrades=computed(()=>data.value?.upgrades||[])
const operations=computed(()=>operationRows.value)
const venueRequests=computed(()=>operationsData.value?.requests||[])
const openOffers=computed(()=>offers.value.filter(o=>o.status==='OFFERED'))
const acceptedOffers=computed(()=>offers.value.filter(o=>['ACCEPTED','PAID'].includes(o.status)))
const filterOptions=computed(()=>operationsData.value?.filter_options||{stadiums:[],competitions:[],seasons:[],brands:[],teams:[]})
const filteredOffers=computed(()=>offers.value.filter(o=>{
  const f=sponsorFilters.value,q=f.q.trim().toLowerCase();
  return (!q||[o.brand_name,o.competition_name,o.stadium_name,o.industry].some(v=>String(v||'').toLowerCase().includes(q)))
    &&(!f.status||o.status===f.status)&&(!f.season_id||Number(o.season_id)===Number(f.season_id))
    &&(!f.competition_id||Number(o.competition_id)===Number(f.competition_id))&&(!f.stadium_id||Number(o.stadium_id)===Number(f.stadium_id))
    &&(!f.brand_id||Number(o.brand_id)===Number(f.brand_id))
}))
const qualityItems=[['pitch_quality','Mặt cỏ',Goal],['seating_quality','Ghế ngồi',Armchair],['stands_quality','Khán đài',Building2],['lighting_quality','Ánh sáng',Lightbulb],['technology_quality','Công nghệ',Wifi],['hospitality_quality','VIP',Crown],['parking_quality','Bãi xe',Car],['security_quality','An ninh',ShieldCheck],['commercial_quality','Thương mại',Store],['atmosphere_quality','Không khí',Sparkles]]

async function setup(){try{const tasks=[api.get('/stadium-upgrades/catalog'),api.get('/sponsor-brands')];if(isAdmin.value)tasks.push(api.get('/clubs',{limit:100,status:'APPROVED'}));const r=await Promise.all(tasks);catalog.value=r[0].data;brands.value=r[1].data;if(isAdmin.value){clubs.value=r[2].data||[];if(!clubId.value&&clubs.value.length)clubId.value=clubs.value[0].id}else clubId.value=authStore.user.value?.clubId;await load()}catch(e){uiStore.notify(e.message,'error')}}
async function load(){if(!clubId.value)return;try{const [r,o]=await Promise.all([api.get('/stadium-centre/summary',{club_id:clubId.value}),api.get('/stadium-operations/dashboard',{club_id:clubId.value})]);data.value=r.data;operationsData.value=o.data;await loadOperationMatches()}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
async function loadOperationMatches(page=matchFilters.value.page){matchFilters.value.page=page;const r=await api.get('/stadium-operations/matches',{...matchFilters.value,club_id:clubId.value});operationRows.value=r.data.rows||[];operationMeta.value=r.data}
function resetMatchFilters(){matchFilters.value={q:'',team:'',stadium_id:'',competition_id:'',season_id:'',brand_id:'',match_kind:'',timing:'ALL',ad_status:'',eligibility_status:'',assignment_method:'',min_value:'',max_value:'',date_from:'',date_to:'',sort:'NEWEST',page:1,limit:30};loadOperationMatches(1)}
watch(clubId,()=>load())
onMounted(setup)
function resetStadiumForm(){stadiumForm.value={name:'',city:'',country_name:'Việt Nam',capacity_total:12000,standard_seats:11000,vip_seats:1000,hospitality_boxes:4,default_standard_ticket:100000,default_vip_ticket:500000,concession_per_head:35000,parking_per_head:8000,pitch_quality:48,seating_quality:45,stands_quality:45,lighting_quality:50,technology_quality:38,hospitality_quality:35,parking_quality:40,security_quality:50,commercial_quality:38,atmosphere_quality:52,relationship_type:'OWNED'}}
async function createStadium(){busy.value=true;try{await api.post('/stadiums',{...stadiumForm.value,club_id:clubId.value});uiStore.notify('Đã tạo sân và gắn vào CLB.');modal.value='';resetStadiumForm();load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function setPrimary(stadium){try{await api.post(`/stadiums/${stadium.id}/set-primary`,{club_id:clubId.value});uiStore.notify(`${stadium.name} đã trở thành sân nhà chính.`);load()}catch(e){uiStore.notify(e.message,'error')}}
async function openRent(){try{const r=await api.get('/public/stadiums');publicStadiums.value=(r.data||[]).filter(s=>!stadiums.value.some(x=>Number(x.id)===Number(s.id)));rentForm.value={stadium_id:publicStadiums.value[0]?.id||'',relationship_type:'LEASED',lease_fee_per_match:'200000000',owner_revenue_share_pct:'5',starts_on:'',ends_on:''};modal.value='rent'}catch(e){uiStore.notify(e.message,'error')}}
async function rentStadium(){busy.value=true;try{await api.post(`/stadiums/${rentForm.value.stadium_id}/links`,{...rentForm.value,club_id:clubId.value});uiStore.notify('Đã thiết lập quyền thuê sân.');modal.value='';load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function openMatchRequest(match){selectedMatch.value=match;const r=await api.get('/public/stadiums');publicStadiums.value=r.data||[];requestForm.value={source_match_id:match.match_id,stadium_id:publicStadiums.value[0]?.id||'',proposed_fee:0,proposed_owner_share_pct:5,note:''};modal.value='matchRequest'}
async function submitMatchRequest(){busy.value=true;try{await api.post('/stadium-operations/requests',{...requestForm.value,match_kind:'REGULAR',club_id:clubId.value});uiStore.notify('Đã gửi yêu cầu sân cho FIFA duyệt.');modal.value='';await load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function reviewRequest(item,status){busy.value=true;try{await api.patch(`/stadium-operations/requests/${item.id}/review`,{status});uiStore.notify(status==='APPROVED'?'Đã duyệt và gán sân cho trận.':'Đã từ chối yêu cầu sân.');await load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function autoAssignAll(){busy.value=true;try{const r=await api.post('/stadium-operations/auto-assign-pending',{}, {timeout:120000});const reason=r.data.reason_summary?.[0];const message=`Đã phân sân ${r.data.assigned}/${r.data.total} trận${r.data.skipped?`; còn ${r.data.skipped} trận chưa phân${reason?` — ${reason.message} (${reason.count} trận)`:''}`:'.'}`;uiStore.notify(message,r.data.skipped?'error':'success');await load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function openStatement(operation){try{selectedStatement.value=(await api.get(`/stadium-operations/${operation.id}/statement`)).data;modal.value='statement'}catch(e){uiStore.notify(e.message,'error')}}
function openMatchday(match){selectedMatch.value=match;selectedFinance.value=match.finance_id?match:null;matchForm.value={stadium_id:match.assigned_stadium_id||match.stadium_id||primaryStadium.value?.id||'',simulation_mode:'RANDOM',occupancy_pct:Math.round(Number(match.occupancy_pct||75)),standard_ticket_price:Number(primaryStadium.value?.default_standard_ticket||120000),vip_ticket_price:Number(primaryStadium.value?.default_vip_ticket||600000)};modal.value='matchday'}
async function simulate(){busy.value=true;try{const r=await api.post(`/stadium-matchdays/${selectedMatch.value.match_id}/simulate`,matchForm.value);selectedFinance.value=r.data;uiStore.notify(matchForm.value.simulation_mode==='RANDOM'?'Đã random sức hút, khán giả và doanh thu.':'Đã tính doanh thu theo dữ liệu nhập tay.');await load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function settle(matchId){busy.value=true;try{const r=await api.post(`/stadium-matchdays/${matchId}/settle`,{});selectedFinance.value=r.data;uiStore.notify('Đã chốt doanh thu và ghi sổ vào ví CLB.');await load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function randomSponsors(match=selectedMatch.value){const stadiumId=match?.stadium_id||primaryStadium.value?.id;if(!match||!stadiumId){uiStore.notify('Hãy chọn trận và sân trước.','error');return}busy.value=true;try{const r=await api.post('/sponsorship/offers/random',{club_id:clubId.value,match_id:match.match_id,stadium_id:stadiumId});uiStore.notify(r.data.count?`Có ${r.data.count} lời mời tài trợ mới.`:'Lần này không có nhãn hàng phù hợp — đúng chất hên xui!');active.value='sponsors';modal.value='';await load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function updateOffer(offer,status){busy.value=true;try{await api.patch(`/sponsorship/offers/${offer.id}/status`,{status});uiStore.notify(status==='ACCEPTED'?`Đã ký với ${offer.brand_name}.`:`Đã từ chối ${offer.brand_name}.`);load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
function openManualSponsor(){const match=matches.value.find(m=>m.status!=='CANCELLED');sponsorForm.value={match_id:match?.match_id||'',stadium_id:primaryStadium.value?.id||'',brand_id:brands.value[0]?.id||'',offer_type:'MATCH_PARTNER',amount:'1000000000'};modal.value='manualSponsor'}
async function createManualSponsor(){busy.value=true;try{const match=matches.value.find(m=>Number(m.match_id)===Number(sponsorForm.value.match_id));await api.post('/sponsorship/offers/manual',{...sponsorForm.value,club_id:clubId.value,competition_id:match?.competition_id||null});uiStore.notify('Đã tạo lời mời tài trợ thủ công.');modal.value='';load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function startUpgrade(stadium,item){busy.value=true;try{await api.post(`/stadiums/${stadium.id}/upgrades`,{club_id:clubId.value,catalog_id:item.id});uiStore.notify(`Đã khởi công: ${item.name}.`);load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function completeUpgrade(item){busy.value=true;try{await api.post(`/stadium-upgrades/${item.id}/complete`,{force:isAdmin.value});uiStore.notify(`Nâng cấp ${item.upgrade_name} đã hoàn thành!`);load()}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
function upgradeProgress(item){if(item.status==='COMPLETED')return 100;const total=Math.max(1,Number(item.total_seconds||1)),elapsed=Math.max(0,Number(item.elapsed_seconds||0));return Math.min(99,Math.round(elapsed/total*100))}
function stadiumClassName(value){return {WORLD_CLASS:'World Class',ELITE:'Elite',A:'Hạng A',B:'Hạng B',C:'Hạng C'}[value]||value}
function offerStatus(value){return {NONE:'Chưa có',OFFERED:'Đang chờ',ACCEPTED:'Đã nhận',REJECTED:'Đã từ chối',EXPIRED:'Hết hạn',PAID:'Đã thanh toán'}[value]||value}
function offerType(value){return {MATCH_PARTNER:'Đối tác trận đấu',LED_BOARD:'Biển LED',VIP_LOUNGE:'Khu VIP',STADIUM_PARTNER:'Đối tác sân',SEASON_PARTNER:'Đối tác mùa'}[value]||value}
function openUpgradeFromCompliance(stadium){const owned=stadiums.value.find(s=>Number(s.id)===Number(stadium.id)&&s.relationship_type==='OWNED');if(!owned){uiStore.notify('Chỉ sân CLB sở hữu mới có thể nâng cấp. Sân thuê cần chủ sở hữu đầu tư.','error');return}selectedStadium.value=owned;active.value='upgrades'}
</script>

<template><div><PageHeader eyebrow="Stadium Intelligence 2.0.24" title="Trung tâm sân vận động" description="Điều phối sân, tìm trận, nhận quảng cáo theo giải và đối soát doanh thu trong một trung tâm đồng bộ."><select v-if="isAdmin" v-model="clubId" class="select club-select"><option v-for="c in clubs" :key="c.id" :value="c.id">{{ c.name }}</option></select><button class="btn" @click="load"><RefreshCw :size="17"/>Làm mới</button></PageHeader>
<LoadingBlock v-if="loading"/><template v-else-if="data"><section class="hero glass"><div class="hero-copy"><div class="eyebrow"><Sparkles :size="14"/>MATCHDAY BUSINESS</div><h2>{{ currentClub?.name }}</h2><p>Sân nhà càng hiện đại, sức hút khán giả, vé VIP và khả năng nhận hợp đồng quảng cáo càng cao.</p><div class="hero-actions"><button class="btn btn-primary" @click="modal='stadium'"><Plus :size="17"/>Tạo sân mới</button><button class="btn" @click="openRent"><KeyRound :size="17"/>Thuê sân</button></div></div><StadiumArena v-if="primaryStadium" :stadium="primaryStadium" compact/><div v-else class="hero-empty"><Building2 :size="44"/><b>CLB chưa có sân</b><span>Hãy tạo sân riêng hoặc thuê sân đang hoạt động.</span></div></section>
<div class="metrics grid-4"><article class="glass stat-card"><Landmark :size="19" class="text-primary"/><div class="stat-value">{{ stadiums.length }}</div><div class="stat-label">Sân đang khai thác</div></article><article class="glass stat-card"><Users :size="19" class="text-green"/><div class="stat-value">{{ number(operationsData?.totals?.avg_occupancy||0,1) }}%</div><div class="stat-label">Lấp đầy trung bình</div></article><article class="glass stat-card"><Ticket :size="19" class="text-yellow"/><div class="stat-value">{{ number(operationsData?.totals?.attendance||0,0) }}</div><div class="stat-label">Lượt khán giả</div></article><article class="glass stat-card"><WalletCards :size="19" class="text-green"/><div class="stat-value">{{ money(operationsData?.totals?.owner_payout||0,true) }}</div><div class="stat-label">Đã trả chủ sân</div></article></div>
<div class="tabs glass"><button v-for="tab in tabs" :key="tab[0]" :class="{active:active===tab[0]}" @click="active=tab[0]"><component :is="tab[2]" :size="17"/>{{ tab[1] }}<span v-if="tab[0]==='sponsors'&&openOffers.length">{{ openOffers.length }}</span></button></div>
<section v-if="active==='overview'" class="page-grid"><div class="section-title"><div><h2>Tài sản sân đấu</h2><p>Sở hữu nhiều sân, chọn sân nhà chính hoặc thuê sân khác cho trận lớn.</p></div><div class="toolbar-actions"><button class="btn" @click="openRent"><KeyRound :size="16"/>Thuê sân</button><button class="btn btn-primary" @click="modal='stadium'"><Plus :size="16"/>Thêm sân</button></div></div><EmptyState v-if="!stadiums.length" title="Chưa có sân vận động" description="Tạo sân đầu tiên để mở khóa vé, tài trợ và nâng cấp."/><div v-else class="stadium-grid"><article v-for="s in stadiums" :key="s.link_id" class="stadium-card glass card-hover"><StadiumArena :stadium="s" compact/><div class="stadium-body"><div class="stadium-head"><div><span class="badge" :class="s.is_primary?'yellow':'blue'">{{ s.is_primary?'Sân nhà chính':s.relationship_type }}</span><h3>{{ s.name }}</h3><p><MapPin :size="13"/>{{ s.city||'Chưa cập nhật' }} · {{ s.country_name }}</p></div><div class="rating" :style="{'--p':`${s.rating_score}%`}"><b>{{ number(s.rating_score,0) }}</b><small>{{ stadiumClassName(s.stadium_class) }}</small></div></div><div class="stadium-stats"><span><Users/>{{ number(s.capacity_total,0) }} ghế</span><span><Crown/>{{ number(s.vip_seats,0) }} VIP</span><span><WalletCards/>{{ money(s.default_standard_ticket,true) }}/vé</span></div><div class="quality-mini"><div v-for="q in qualityItems.slice(0,5)" :key="q[0]"><span>{{ q[1] }}</span><i><b :style="{width:`${s[q[0]]}%`}"/></i></div></div><div class="actions"><button v-if="!s.is_primary" class="btn btn-sm" @click="setPrimary(s)"><Star :size="14"/>Chọn sân chính</button><button class="btn btn-sm btn-primary" @click="selectedStadium=s;active='upgrades'"><Construction :size="14"/>Nâng cấp</button></div></div></article></div></section>
<section v-else-if="active==='compliance'" class="page-grid"><StadiumCompliancePanel :club-id="clubId" :matches="matches" :is-admin="isAdmin" @updated="load" @select-upgrade="openUpgradeFromCompliance"/></section>
<section v-else-if="active==='matchday'" class="page-grid"><div class="section-title"><div><h2>Matchday Revenue Lab</h2><p>Random có kiểm soát dựa trên quy mô giải, thứ hạng, phong độ, ngôi sao và chất lượng sân.</p></div></div><EmptyState v-if="!matches.length" title="Chưa có trận sân nhà" description="Khi CLB có trận sân nhà, hệ thống sẽ cho mô phỏng vé và doanh thu."/><div v-else class="match-list"><article v-for="m in matches" :key="m.match_id" class="glass match-row"><div class="match-main"><span class="badge blue">{{ m.competition_name }}</span><h3>{{ m.home_club_name }} <b>vs</b> {{ m.away_club_name||'Chờ đối thủ' }}</h3><p>{{ date(m.scheduled_at,true) }} · {{ m.stage_type==='KNOCKOUT'?'Loại trực tiếp':'Vòng bảng' }}</p><span v-if="m.stadium_eligibility_status" class="badge" :class="m.stadium_eligibility_status==='ELIGIBLE'?'green':m.stadium_eligibility_status==='CONDITIONAL'?'yellow':m.stadium_eligibility_status==='OVERRIDDEN'?'blue':'red'">{{ m.assigned_stadium_name }} · {{ m.stadium_eligibility_status }}</span></div><div v-if="m.finance_id" class="match-kpis"><span><Users/>{{ number(m.attendance_total,0) }}</span><span><Ticket/>{{ number(m.occupancy_pct,1) }}%</span><strong :class="Number(m.net_revenue)>=0?'text-green':'text-red'">{{ money(m.net_revenue,true) }}</strong></div><div class="actions"><button class="btn btn-sm" @click="openMatchRequest(m)"><KeyRound :size="14"/>Yêu cầu sân</button><button class="btn btn-sm" @click="openMatchday(m)"><Dices :size="14"/>{{ m.finance_id?'Mô phỏng lại':'Mô phỏng' }}</button><button v-if="m.finance_id&&m.finance_status==='DRAFT'" class="btn btn-sm btn-success" @click="settle(m.match_id)"><Check :size="14"/>Chốt doanh thu</button><span v-if="m.finance_status==='SETTLED'" class="badge green">Đã vào ví</span></div></article></div></section>
<section v-else-if="active==='operations'" class="page-grid">
  <div class="section-title"><div><h2>Tìm kiếm & điều phối trận đấu</h2><p>Lọc đồng thời theo sân, giải, đội tuyển/CLB, mùa, quảng cáo, giá trị và trạng thái trận.</p></div><button v-if="isAdmin" class="btn btn-primary" :disabled="busy" @click="autoAssignAll"><Dices :size="16"/>Phân sân & đề xuất quảng cáo</button></div>
  <form class="smart-filter glass" @submit.prevent="loadOperationMatches(1)">
    <div class="filter-grid">
      <label class="filter-wide"><span>Tìm đội, quốc gia, giải hoặc sân</span><input v-model="matchFilters.q" class="input" placeholder="Ví dụ: Việt Nam, World Cup, Barcelona..."/></label>
      <label><span>CLB / quốc gia</span><select v-model="matchFilters.team" class="select"><option value="">Tất cả đội</option><option v-for="t in filterOptions.teams" :key="t.team_name" :value="t.team_name">{{ t.team_name }}</option></select></label>
      <label><span>Sân</span><select v-model="matchFilters.stadium_id" class="select"><option value="">Tất cả sân</option><option v-for="s in filterOptions.stadiums" :key="s.id" :value="s.id">{{ s.name }}</option></select></label>
      <label><span>Giải đấu</span><select v-model="matchFilters.competition_id" class="select"><option value="">Tất cả giải</option><option v-for="c in filterOptions.competitions" :key="c.id" :value="c.id">{{ c.name }}</option></select></label>
      <label><span>Mùa</span><select v-model="matchFilters.season_id" class="select"><option value="">Tất cả mùa</option><option v-for="s in filterOptions.seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label>
      <label><span>Cấp trận</span><select v-model="matchFilters.match_kind" class="select"><option value="">Mọi cấp</option><option value="REGULAR">CLB</option><option value="WORLD_CUP">World Cup</option><option value="NATIONAL_CUP">Đội tuyển quốc gia</option></select></label>
      <label><span>Thời điểm</span><select v-model="matchFilters.timing" class="select"><option value="ALL">Tất cả</option><option value="UPCOMING">Chưa diễn ra</option><option value="FINISHED">Đã diễn ra</option><option value="UNSCHEDULED">Chưa có lịch</option></select></label>
      <label><span>Quảng cáo</span><select v-model="matchFilters.ad_status" class="select"><option value="">Mọi trạng thái</option><option value="NONE">Chưa có</option><option value="OFFERED">Chờ CLB duyệt</option><option value="ACCEPTED">Đã nhận</option><option value="PAID">Đã thanh toán</option><option value="REJECTED">Đã từ chối</option></select></label>
      <label><span>Thương hiệu</span><select v-model="matchFilters.brand_id" class="select"><option value="">Tất cả thương hiệu</option><option v-for="b in filterOptions.brands" :key="b.id" :value="b.id">{{ b.name }}</option></select></label>
      <label><span>Tiêu chuẩn sân</span><select v-model="matchFilters.eligibility_status" class="select"><option value="">Tất cả</option><option value="ELIGIBLE">Đạt chuẩn</option><option value="CONDITIONAL">Có điều kiện</option><option value="OVERRIDDEN">FIFA ngoại lệ</option></select></label>
      <label><span>Cách phân sân</span><select v-model="matchFilters.assignment_method" class="select"><option value="">Tất cả</option><option value="AUTOMATIC">Hệ thống tự xếp</option><option value="FIFA">FIFA chỉ định</option><option value="CLUB_REQUEST">CLB yêu cầu</option></select></label>
      <label><span>Giá trị từ</span><input v-model="matchFilters.min_value" type="number" min="0" class="input" placeholder="0"/></label>
      <label><span>Giá trị đến</span><input v-model="matchFilters.max_value" type="number" min="0" class="input" placeholder="Không giới hạn"/></label>
      <label><span>Từ ngày</span><input v-model="matchFilters.date_from" type="date" class="input"/></label>
      <label><span>Đến ngày</span><input v-model="matchFilters.date_to" type="date" class="input"/></label>
      <label><span>Sắp xếp</span><select v-model="matchFilters.sort" class="select"><option value="NEWEST">Mới nhất</option><option value="OLDEST">Cũ nhất</option><option value="VALUE_DESC">Giá trị cao nhất</option><option value="VALUE_ASC">Giá trị thấp nhất</option><option value="STADIUM">Theo sân</option></select></label>
    </div><div class="filter-actions"><span>{{ number(operationMeta.total,0) }} kết quả</span><button type="button" class="btn btn-sm" @click="resetMatchFilters">Xóa bộ lọc</button><button class="btn btn-sm btn-primary"><RefreshCw :size="14"/>Áp dụng</button></div>
  </form>
  <div class="metrics grid-4"><article class="glass stat-card"><Ticket/><div class="stat-value">{{ number(operationsData?.totals?.match_count,0) }}</div><div class="stat-label">Trận đã có sân</div></article><article class="glass stat-card"><Users/><div class="stat-value">{{ number(operationsData?.totals?.avg_occupancy,1) }}%</div><div class="stat-label">Lấp đầy</div></article><article class="glass stat-card"><Construction/><div class="stat-value">{{ money(operationsData?.totals?.damage_cost||0,true) }}</div><div class="stat-label">Thiệt hại</div></article><article class="glass stat-card"><WalletCards/><div class="stat-value">{{ money(operationsData?.totals?.owner_payout||0,true) }}</div><div class="stat-label">Đã trả chủ sân</div></article></div>
  <div v-if="venueRequests.length" class="request-list"><article v-for="r in venueRequests" :key="r.id" class="glass match-row"><div class="match-main"><span class="badge" :class="r.status==='PENDING'?'yellow':r.status==='APPROVED'?'green':'red'">{{ r.status }}</span><h3>{{ r.requesting_club_name }} yêu cầu {{ r.stadium_name }}</h3><p>Phí đề xuất {{ money(r.proposed_fee,true) }} · chia {{ number(r.proposed_owner_share_pct,1) }}%</p></div><div v-if="isAdmin&&r.status==='PENDING'" class="actions"><button class="btn btn-sm btn-danger" @click="reviewRequest(r,'REJECTED')">Từ chối</button><button class="btn btn-sm btn-success" @click="reviewRequest(r,'APPROVED')"><Check :size="14"/>Duyệt</button></div></article></div>
  <EmptyState v-if="!operations.length" title="Không tìm thấy trận phù hợp" description="Hãy nới điều kiện hoặc xóa bộ lọc để xem thêm trận."/>
  <div v-else class="match-list"><article v-for="o in operations" :key="o.id" class="glass match-row"><div class="match-main"><div class="operation-badges"><span class="badge blue">{{ o.match_kind==='REGULAR'?'CLB':o.match_kind==='WORLD_CUP'?'WORLD CUP':'QUỐC GIA' }} · {{ o.assignment_method }}</span><span class="badge" :class="o.match_status==='FINISHED'?'green':'yellow'">{{ o.match_status==='FINISHED'?'Đã diễn ra':'Chưa diễn ra' }}</span><span class="badge" :class="o.sponsor_status==='PAID'||o.sponsor_status==='ACCEPTED'?'green':o.sponsor_status==='OFFERED'?'yellow':o.sponsor_status==='NONE'?'blue':'red'">QC: {{ offerStatus(o.sponsor_status) }}</span></div><h3>{{ o.home_name||'Chờ đội' }} <b>vs</b> {{ o.away_name||'Chờ đội' }}</h3><p>{{ o.competition_name }} · {{ o.season_name }} · {{ o.stadium_name }} · {{ date(o.scheduled_at,true) }}</p><div class="operation-meta"><span>Giá trị {{ o.value_is_estimated?'ước tính':'thực tế' }}: <b>{{ money(o.match_value,true) }}</b></span><span v-if="o.sponsor_names">Quảng cáo: {{ o.sponsor_names }} · {{ money(o.sponsor_value,true) }}</span><span>Tình trạng sân {{ number(o.condition_pct,1) }}%</span></div></div><div v-if="o.finance_id" class="match-kpis"><span><Users/>{{ number(o.attendance_total,0) }}</span><span><Ticket/>{{ number(o.occupancy_pct,1) }}%</span><strong class="text-green">{{ money(o.owner_payout,true) }}</strong></div><button class="btn btn-sm" @click="openStatement(o)">Xem sao kê</button></article></div>
  <div v-if="operationMeta.pages>1" class="pagination"><button class="btn btn-sm" :disabled="operationMeta.page<=1" @click="loadOperationMatches(operationMeta.page-1)">Trang trước</button><span>Trang {{ operationMeta.page }}/{{ operationMeta.pages }}</span><button class="btn btn-sm" :disabled="operationMeta.page>=operationMeta.pages" @click="loadOperationMatches(operationMeta.page+1)">Trang sau</button></div>
</section>
<section v-else-if="active==='sponsors'" class="page-grid">
  <div class="section-title"><div><h2>Quảng cáo tự động theo sân & giải</h2><p>Khi FIFA hoặc hệ thống phân sân, các nhãn hàng phù hợp được đề xuất tự động. CLB chỉ cần nhận hoặc từ chối.</p></div></div>
  <div class="sponsor-note glass"><Sparkles/><div><b>Hệ thống ưu tiên thông minh</b><p>Sân tốt, giải hấp dẫn và lịch sử từng hợp tác làm tăng giá trị cũng như khả năng thương hiệu quay lại. Hợp đồng đã nhận được thanh toán tự động khi giải kết thúc và lưu vào lịch sử.</p></div></div>
  <div class="smart-filter glass"><div class="filter-grid sponsor-filter"><label class="filter-wide"><span>Tìm thương hiệu, giải hoặc sân</span><input v-model="sponsorFilters.q" class="input" placeholder="Nhập từ khóa..."/></label><label><span>Trạng thái</span><select v-model="sponsorFilters.status" class="select"><option value="">Tất cả</option><option value="OFFERED">Chờ quyết định</option><option value="ACCEPTED">Đã nhận, chờ trả</option><option value="PAID">Đã thanh toán</option><option value="REJECTED">Đã từ chối</option><option value="EXPIRED">Hết hạn</option></select></label><label><span>Mùa</span><select v-model="sponsorFilters.season_id" class="select"><option value="">Tất cả mùa</option><option v-for="s in filterOptions.seasons" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label><span>Giải</span><select v-model="sponsorFilters.competition_id" class="select"><option value="">Tất cả giải</option><option v-for="c in filterOptions.competitions" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label><span>Sân</span><select v-model="sponsorFilters.stadium_id" class="select"><option value="">Tất cả sân</option><option v-for="s in filterOptions.stadiums" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label><span>Thương hiệu</span><select v-model="sponsorFilters.brand_id" class="select"><option value="">Tất cả</option><option v-for="b in filterOptions.brands" :key="b.id" :value="b.id">{{ b.name }}</option></select></label></div><div class="filter-actions"><span>{{ filteredOffers.length }}/{{ offers.length }} đề nghị & giao dịch</span></div></div>
  <EmptyState v-if="!filteredOffers.length" title="Không có đề nghị phù hợp" description="Đề nghị mới tự xuất hiện sau khi sân được phân cho trận của một giải."/>
  <div v-else class="offer-grid"><article v-for="o in filteredOffers" :key="o.id" class="offer-card glass" :style="{'--brand':o.accent_hex||'var(--primary)'}"><div class="brand-mark">{{ o.brand_name?.slice(0,2).toUpperCase() }}</div><div class="offer-head"><span class="badge" :class="o.status==='OFFERED'?'yellow':o.status==='ACCEPTED'||o.status==='PAID'?'green':'red'">{{ offerStatus(o.status) }}</span><small>{{ o.brand_tier }}</small></div><h3>{{ o.brand_name }}</h3><p>{{ o.industry }} · {{ offerType(o.offer_type) }}</p><div class="offer-money">{{ money(o.amount) }}</div><div class="offer-meta"><span v-if="o.generation_source==='AUTO_STADIUM_COMPETITION'">Tự đề xuất · ưu tiên {{ number(o.preference_score,0) }}/100</span><span>Sức hút {{ number(o.attractiveness_score,0) }}/100</span><span v-if="o.competition_name">{{ o.competition_name }} · {{ o.season_name }}</span><span v-if="o.stadium_name">Sân {{ o.stadium_name }}</span><span v-if="o.status==='ACCEPTED'">Đã nhận · thanh toán sau khi giải kết thúc</span><span v-if="o.status==='PAID'">Đã thanh toán {{ date(o.paid_at,true) }}</span></div><div v-if="o.status==='OFFERED'" class="actions"><button class="btn btn-sm btn-danger" @click="updateOffer(o,'REJECTED')">Từ chối</button><button class="btn btn-sm btn-success" @click="updateOffer(o,'ACCEPTED')"><Check :size="14"/>Chấp nhận</button></div></article></div>
</section>
<section v-else class="page-grid"><div class="section-title"><div><h2>Upgrade Planner</h2><p>Đầu tư qua ví CLB; nâng cấp hoàn tất làm tăng sức chứa, chất lượng và sức hút quảng cáo.</p></div><select v-model="selectedStadium" class="select upgrade-select"><option :value="null">Chọn sân</option><option v-for="s in stadiums.filter(x=>x.relationship_type==='OWNED')" :key="s.id" :value="s">{{ s.name }}</option></select></div><div v-if="upgrades.length" class="upgrade-progress"><article v-for="u in upgrades.filter(x=>x.status==='IN_PROGRESS')" :key="u.id" class="glass"><div class="upgrade-icon"><Construction/></div><div><span class="eyebrow">Đang thi công · {{ u.stadium_name }}</span><h3>{{ u.upgrade_name }}</h3><p>{{ date(u.expected_at,true) }} · {{ money(u.final_cost,true) }}</p><div class="progress"><b :style="{width:`${upgradeProgress(u)}%`}"/></div></div><button class="btn btn-sm" @click="completeUpgrade(u)"><Check :size="14"/>{{ isAdmin?'Hoàn tất ngay':'Kiểm tra hoàn tất' }}</button></article></div><div v-if="!selectedStadium" class="glass select-stadium"><Construction :size="42"/><h3>Chọn sân sở hữu để lên kế hoạch</h3></div><template v-else><div class="upgrade-stage glass"><StadiumArena :stadium="selectedStadium" compact/><div><span class="eyebrow">{{ selectedStadium.name }}</span><h2>{{ stadiumClassName(selectedStadium.stadium_class) }} · {{ number(selectedStadium.rating_score,1) }}/100</h2><div class="quality-list"><div v-for="q in qualityItems" :key="q[0]"><component :is="q[2]" :size="15"/><span>{{ q[1] }}</span><i><b :style="{width:`${selectedStadium[q[0]]}%`}"/></i><strong>{{ selectedStadium[q[0]] }}</strong></div></div></div></div><div class="catalog-grid"><article v-for="item in catalog" :key="item.id" class="glass upgrade-card"><div class="upgrade-top"><span class="badge blue">{{ item.category }}</span><span><Timer :size="14"/>{{ item.duration_days }} ngày</span></div><h3>{{ item.name }}</h3><p>{{ item.description }}</p><div class="upgrade-impact"><span v-if="item.capacity_add">+{{ number(item.capacity_add,0) }} ghế</span><span v-if="item.vip_seats_add">+{{ number(item.vip_seats_add,0) }} VIP</span><span v-if="item.technology_bonus">+{{ item.technology_bonus }} công nghệ</span><span v-if="item.commercial_bonus">+{{ item.commercial_bonus }} thương mại</span></div><div class="upgrade-bottom"><b>{{ money(item.base_cost,true) }}</b><button class="btn btn-sm btn-primary" :disabled="busy" @click="startUpgrade(selectedStadium,item)">Đầu tư<ChevronRight :size="14"/></button></div></article></div></template></section></template>
<BaseModal :open="modal==='stadium'" title="Tạo sân vận động" width="900px" @close="modal=''" ><form class="form-grid" @submit.prevent="createStadium"><label><span class="label">Tên sân</span><input v-model="stadiumForm.name" class="input" required placeholder="Arena of Champions"/></label><label><span class="label">Thành phố</span><input v-model="stadiumForm.city" class="input" placeholder="TP. Hồ Chí Minh"/></label><label><span class="label">Sức chứa</span><input v-model.number="stadiumForm.capacity_total" type="number" class="input" min="100" required/></label><label><span class="label">Ghế thường</span><input v-model.number="stadiumForm.standard_seats" type="number" class="input" min="0" required/></label><label><span class="label">Ghế VIP</span><input v-model.number="stadiumForm.vip_seats" type="number" class="input" min="0" required/></label><label><span class="label">Sky box</span><input v-model.number="stadiumForm.hospitality_boxes" type="number" class="input" min="0"/></label><label><span class="label">Vé thường</span><input v-model="stadiumForm.default_standard_ticket" type="number" class="input" min="0"/></label><label><span class="label">Vé VIP</span><input v-model="stadiumForm.default_vip_ticket" type="number" class="input" min="0"/></label><div class="form-group full initial-quality"><div v-for="q in qualityItems" :key="q[0]"><label :for="q[0]">{{ q[1] }} <b>{{ stadiumForm[q[0]] }}</b></label><input :id="q[0]" v-model.number="stadiumForm[q[0]]" type="range" min="1" max="100"/></div></div><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Tạo sân</button></div></form></BaseModal>
<BaseModal :open="modal==='rent'" title="Thuê sân vận động" width="640px" @close="modal=''" ><form class="form-grid" @submit.prevent="rentStadium"><label class="form-group full"><span class="label">Sân muốn thuê</span><select v-model="rentForm.stadium_id" class="select" required><option v-for="s in publicStadiums" :key="s.id" :value="s.id">{{ s.name }} · {{ number(s.capacity_total,0) }} ghế · {{ s.clubs||'Sân trung lập' }}</option></select></label><label><span class="label">Phí thuê mỗi trận</span><input v-model="rentForm.lease_fee_per_match" type="number" class="input" min="0"/></label><label><span class="label">Chia doanh thu chủ sân (%)</span><input v-model="rentForm.owner_revenue_share_pct" type="number" class="input" min="0" max="80" step="0.1"/></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Xác nhận thuê</button></div></form></BaseModal>
<BaseModal :open="modal==='matchday'" title="Mô phỏng ngày thi đấu" width="760px" @close="modal=''" ><div v-if="selectedMatch" class="match-modal"><div class="match-banner"><span>{{ selectedMatch.competition_name }}</span><h2>{{ selectedMatch.home_club_name }} <b>vs</b> {{ selectedMatch.away_club_name }}</h2></div><div class="form-grid"><label class="form-group full"><span class="label">Sân tổ chức</span><select v-model="matchForm.stadium_id" class="select"><option v-for="s in stadiums" :key="s.link_id" :value="s.id">{{ s.name }} · {{ number(s.capacity_total,0) }} ghế</option></select></label><label><span class="label">Chế độ</span><select v-model="matchForm.simulation_mode" class="select"><option value="RANDOM">Random thông minh</option><option value="MANUAL">Nhập tay</option></select></label><label v-if="matchForm.simulation_mode==='MANUAL'"><span class="label">Tỷ lệ lấp đầy (%)</span><input v-model.number="matchForm.occupancy_pct" class="input" type="number" min="1" max="100"/></label><label v-if="matchForm.simulation_mode==='MANUAL'"><span class="label">Giá vé thường</span><input v-model="matchForm.standard_ticket_price" class="input" type="number"/></label><label v-if="matchForm.simulation_mode==='MANUAL'"><span class="label">Giá vé VIP</span><input v-model="matchForm.vip_ticket_price" class="input" type="number"/></label></div><div v-if="selectedFinance" class="finance-result"><div><span>Lấp đầy</span><b>{{ number(selectedFinance.occupancy_pct,1) }}%</b></div><div><span>Khán giả</span><b>{{ number(selectedFinance.attendance_total,0) }}</b></div><div><span>Doanh thu gộp</span><b>{{ money(selectedFinance.gross_revenue,true) }}</b></div><div><span>Lợi nhuận</span><b :class="Number(selectedFinance.net_revenue)>=0?'text-green':'text-red'">{{ money(selectedFinance.net_revenue,true) }}</b></div></div><div class="actions modal-actions"><button class="btn btn-primary" :disabled="busy" @click="simulate"><Dices :size="16"/>{{ matchForm.simulation_mode==='RANDOM'?'Random trận đấu':'Tính doanh thu' }}</button><button v-if="selectedFinance&&selectedFinance.status==='DRAFT'" class="btn btn-success" :disabled="busy" @click="settle(selectedMatch.match_id)"><Check :size="16"/>Chốt vào ví</button></div></div></BaseModal>
<BaseModal :open="modal==='manualSponsor'" title="Tạo lời mời tài trợ thủ công" width="650px" @close="modal=''" ><form class="form-grid" @submit.prevent="createManualSponsor"><label class="form-group full"><span class="label">Trận đấu</span><select v-model="sponsorForm.match_id" class="select"><option v-for="m in matches" :key="m.match_id" :value="m.match_id">{{ m.home_club_name }} vs {{ m.away_club_name }} · {{ m.competition_name }}</option></select></label><label><span class="label">Thương hiệu</span><select v-model="sponsorForm.brand_id" class="select"><option v-for="b in brands" :key="b.id" :value="b.id">{{ b.name }} · {{ b.brand_tier }}</option></select></label><label><span class="label">Vị trí tài trợ</span><select v-model="sponsorForm.offer_type" class="select"><option value="MATCH_PARTNER">Đối tác trận đấu</option><option value="LED_BOARD">Biển LED</option><option value="VIP_LOUNGE">Khu VIP</option><option value="STADIUM_PARTNER">Đối tác sân</option></select></label><label class="form-group full"><span class="label">Giá trị đề nghị</span><input v-model="sponsorForm.amount" type="number" class="input" min="1"/></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Tạo lời mời</button></div></form></BaseModal>
<BaseModal :open="modal==='matchRequest'" title="Yêu cầu FIFA duyệt sân cho trận" width="680px" @close="modal=''" ><form class="form-grid" @submit.prevent="submitMatchRequest"><label class="form-group full"><span class="label">Sân đề xuất</span><select v-model="requestForm.stadium_id" class="select" required><option v-for="s in publicStadiums" :key="s.id" :value="s.id">{{ s.name }} · {{ number(s.capacity_total,0) }} ghế · rating {{ number(s.rating_score,1) }}</option></select></label><label><span class="label">Phí thuê đề xuất</span><input v-model.number="requestForm.proposed_fee" type="number" min="0" class="input"/></label><label><span class="label">Chia doanh thu chủ sân (%)</span><input v-model.number="requestForm.proposed_owner_share_pct" type="number" min="0" max="80" step="0.1" class="input"/></label><label class="form-group full"><span class="label">Ghi chú cho FIFA</span><textarea v-model="requestForm.note" class="input" rows="3"></textarea></label><div class="form-group full actions"><button type="button" class="btn" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Gửi yêu cầu</button></div></form></BaseModal>
<BaseModal :open="modal==='statement'" title="Sao kê doanh thu & thiệt hại sân" width="820px" @close="modal=''" ><div v-if="selectedStatement" class="statement"><div class="match-banner"><span>{{ selectedStatement.operation.competition_name }} · {{ selectedStatement.operation.stadium_name }}</span><h2>{{ selectedStatement.operation.home_name }} <b>vs</b> {{ selectedStatement.operation.away_name }}</h2></div><div v-if="!selectedStatement.lines.length" class="sponsor-note"><Timer/><p>Trận chưa kết thúc nên chưa có sao kê quyết toán.</p></div><div v-else class="statement-lines"><div v-for="line in selectedStatement.lines" :key="line.id"><span>{{ line.label }}<small>{{ line.explanation }}</small></span><b :class="Number(line.amount)>=0?'text-green':'text-red'">{{ Number(line.amount)>=0?'+':'' }}{{ money(line.amount) }}</b></div></div></div></BaseModal>
